// stapel-tokens: the §68 design tokens as a pure-Kotlin value. The types are hand-written;
// StapelDefaultTokens / StapelPresetTokens are generated by :tools:tokens-gen (emitter compose@1) from
// tokens-source/ and committed under src/commonMain/generated (drift gate: stapelGenerateCheck).
plugins {
    id("stapel.substrate")
}

stapel {
    description = "Stapel design tokens (colour roles, type, spacing, radii, elevation, breakpoints) as a Kotlin value."
}

kotlin {
    sourceSets {
        commonMain {
            kotlin.srcDir("src/commonMain/generated/kotlin")
        }
    }
}

val tokensGen = configurations.create("stapelTokensGen") {
    isCanBeConsumed = false
    isCanBeResolved = true
}
dependencies {
    tokensGen(project(":tools:tokens-gen"))
}

fun JavaExec.tokensGen(check: Boolean) {
    group = "stapel generate"
    classpath = tokensGen
    mainClass.set("stapel.tools.tokens.MainKt")
    args(listOfNotNull("library", "--repo-root", rootDir.absolutePath, if (check) "--check" else null))
    inputs.dir(rootProject.layout.projectDirectory.dir("tokens-source")).withPathSensitivity(PathSensitivity.RELATIVE)
}

tasks.register<JavaExec>("stapelGenerate") {
    description = "Regenerates src/commonMain/generated from tokens-source/ (compose@1)."
    tokensGen(check = false)
    outputs.dir("src/commonMain/generated")
}

val generateCheck = tasks.register<JavaExec>("stapelGenerateCheck") {
    description = "Regenerates in memory and fails on any difference from the committed generated sources."
    tokensGen(check = true)
    inputs.dir("src/commonMain/generated")
    outputs.upToDateWhen { false }
}
tasks.named("check") { dependsOn(generateCheck) }
